/* ===== 59-recorded-leave.js ===== */
/* Approved leave taken from HR email, added to attendance once.
   A day is changed only while it is still a normal working day (P or blank), so a
   weekly off (unless the sheet marks leave on it: anyDay), a holiday or anything HR already marked by hand is left alone. */
const RECORDED_LEAVE = [
  { key: 'lv-ML-011-2026-10', empId: 'ML-011', code: 'PL', dates: ['2026-10-14', '2026-10-15'], note: 'Family function (demo)' },
  { key: 'lv-ML-010-2026-12', empId: 'ML-010', code: 'PL', dates: ['2026-12-02', '2026-12-03', '2026-12-04'], note: 'Approved in advance (demo)' },
];

function applyRecordedLeave() {
  S.recordedLeave = Array.isArray(S.recordedLeave) ? S.recordedLeave : [];
  let changed = false;
  for (const x of RECORDED_LEAVE) {
    if (S.recordedLeave.includes(x.key)) continue;
    S.recordedLeave.push(x.key);
    changed = true;
    const e = empOf(x.empId);
    if (!e) continue;
    for (const d of x.dates) {
      const a = attFor(d.slice(0, 7), e),
        i = Number(d.slice(8)) - 1;
      if (a[i] === 'P' || !a[i] || (x.anyDay && a[i] === 'WO')) a[i] = x.code;
    }
  }
  if (changed) save();
  return changed;
}
applyRecordedLeave();
// a data file connected later (or a restored backup) gets the same one-time update
afterRender.push(() => {
  if (!RECORDED_LEAVE.every((x) => (S.recordedLeave || []).includes(x.key)) && applyRecordedLeave()) render();
});

/* ===== 60-privacy.js ===== */
/* ============================================================
   HIDE AMOUNTS: money is blurred until you press the eye button
   (or click one amount to see just that one). Letters, payslip
   PDFs and Excel downloads always contain the real figures.
   ============================================================ */
const EYE =
  '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg>';
const EYE_OFF =
  '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9.88 9.88a3 3 0 1 0 4.24 4.24"/><path d="M10.73 5.08A10.43 10.43 0 0 1 12 5c6.5 0 10 7 10 7a13.16 13.16 0 0 1-1.67 2.68"/><path d="M6.61 6.61A13.53 13.53 0 0 0 2 12s3.5 7 10 7a9.74 9.74 0 0 0 5.39-1.61"/><path d="M2 2l20 20"/></svg>';
const eyeBtn = document.createElement('button');
eyeBtn.type = 'button';
eyeBtn.id = 'navEye';
$('navDashboard').insertAdjacentElement('beforebegin', eyeBtn);
function setMoneyHidden(h) {
  document.body.classList.toggle('hide-money', h);
  eyeBtn.innerHTML = h ? `${EYE}<span>Show amounts</span>` : `${EYE_OFF}<span>Hide amounts</span>`;
  eyeBtn.classList.toggle('on', !h);
  eyeBtn.setAttribute('aria-pressed', String(!h));
  eyeBtn.title = h ? 'Amounts are hidden. Click to show them.' : 'Click to hide all amounts again.';
  if (h) document.querySelectorAll('.amt-mask.show').forEach((x) => x.classList.remove('show'));
}
eyeBtn.addEventListener('click', () => setMoneyHidden(!document.body.classList.contains('hide-money')));
setMoneyHidden(false); // amounts are visible; the eye button hides them when you want privacy
/* wrap every ₹ / $ amount shown on screen in a span that can be blurred */
const MONEY_RE = /(?:[−-]\s?)?[₹$]\s?\d[\d,]*(?:\.\d+)?(?:\s?(?:L|K|Cr|M)\b)?/g;
const SKIP = 'script,style,textarea,input,select,option,.a4,.pages,.lbody,.paper,.amt-mask,#incxDlg .ix-form';
function maskIn(root) {
  if (!root || (root.nodeType !== 1 && root.nodeType !== 3)) return;
  const el = root.nodeType === 3 ? root.parentElement : root;
  if (!el || el.closest(SKIP)) return;
  const tw = document.createTreeWalker(root.nodeType === 3 ? el : root, NodeFilter.SHOW_TEXT, {
    acceptNode: (n) => {
      MONEY_RE.lastIndex = 0;
      return MONEY_RE.test(n.nodeValue) && !(n.parentElement && n.parentElement.closest(SKIP))
        ? NodeFilter.FILTER_ACCEPT
        : NodeFilter.FILTER_REJECT;
    },
  });
  const list = [];
  while (tw.nextNode()) list.push(tw.currentNode);
  list.forEach((n) => {
    const t = n.nodeValue,
      f = document.createDocumentFragment();
    let last = 0;
    MONEY_RE.lastIndex = 0;
    let mm;
    while ((mm = MONEY_RE.exec(t))) {
      if (mm.index > last) f.appendChild(document.createTextNode(t.slice(last, mm.index)));
      const s = document.createElement('span');
      s.className = 'amt-mask';
      s.textContent = mm[0];
      f.appendChild(s);
      last = mm.index + mm[0].length;
    }
    if (last < t.length) f.appendChild(document.createTextNode(t.slice(last)));
    n.parentNode.replaceChild(f, n);
  });
}
let maskQ = new Set(),
  maskT = 0;
const mo = new MutationObserver((ms) => {
  ms.forEach((m) => {
    if (m.type === 'characterData') maskQ.add(m.target);
    else m.addedNodes.forEach((n) => maskQ.add(n));
  });
  if (!maskT)
    maskT = requestAnimationFrame(() => {
      maskT = 0;
      const q = [...maskQ];
      maskQ.clear();
      q.forEach((n) => {
        if (n.isConnected) maskIn(n);
      });
    });
});
mo.observe(document.body, { childList: true, subtree: true, characterData: true });
maskIn(document.body);
/* clicking one blurred amount shows just that amount */
document.addEventListener(
  'click',
  (ev) => {
    if (!document.body.classList.contains('hide-money')) return;
    const s = ev.target.closest && ev.target.closest('.amt-mask:not(.show)');
    if (!s) return;
    ev.preventDefault();
    ev.stopPropagation();
    s.classList.add('show');
  },
  true,
);

/* ===== 64-one-file.js ===== */
/* "Download HRMS with my data": saves this HRMS as ONE .html file with all the data inside it.
   Open that file on any computer or browser and the data is there; when a browser already holds newer
   data, the browser's data is kept (see load() in app.js). Only in the single-file version (AcmeLabs_HRMS.html). */
function hrmsWithData() {
  const shell = window.HRMS_SHELL;
  if (!shell) return '';
  const all = [...document.querySelectorAll('script')],
    from = all.findIndex((x) => x.textContent.startsWith('/* shell */'));
  const code = all
    .slice(from + 1)
    .filter((x) => !x.textContent.startsWith('/* embedded data */'))
    .map((x) => x.outerHTML)
    .join('\n');
  // inside the JSON '<' only appears in text, where < reads back as '<'
  const data = JSON.stringify(S).replace(/</g, '\\u003c');
  return (
    shell.slice(0, shell.lastIndexOf('</body>')) +
    `<script>/* embedded data */\nwindow.HRMS_EMBEDDED = ${data};\n<\/script>\n` +
    code +
    '\n</body></html>'
  );
}
(() => {
  const anchor = $('exportJson');
  if (!anchor || !window.HRMS_SHELL || $('exportHtml')) return;
  const b = document.createElement('button');
  b.className = 'btn primary';
  b.id = 'exportHtml';
  b.type = 'button';
  b.textContent = 'Download HRMS with my data';
  b.title = 'One .html file with all your data inside. Open it on any computer.';
  b.addEventListener('click', () => {
    save();
    download(`AcmeLabs_HRMS_${new Date().toISOString().slice(0, 10)}.html`, hrmsWithData(), 'text/html');
  });
  anchor.insertAdjacentElement('beforebegin', b);
  // both downloads hold everyone's salary, bank and ID details: say so where they are made
  const row = anchor.parentElement;
  if (row && !$('exportWarn'))
    row.insertAdjacentHTML(
      'afterend',
      '<p class="cell-sub" id="exportWarn">Backups and "HRMS with my data" contain every salary, bank account and ID number. Keep them in a private folder and share only with people allowed to see payroll.</p>',
    );
})();

